function validate([prices]) {
  if (!Array.isArray(prices) || prices.length < 1 || prices.length > 1000) return 'prices needs 1 to 1000 values.';
  if (prices.some(v => !Number.isInteger(v) || v < 1 || v > 100000)) return 'Each price is a whole number from 1 to 100000.';
  return null;
}

