function minimumCoins(prices) {
  const n = prices.length;
  const dp = new Array(n).fill(0);
  for (let i = n - 1; i >= 0; i--) {
    const reach = 2 * i + 2;
    if (reach >= n) {
      dp[i] = prices[i];
      continue;
    }
    let cheapest = Infinity;
    for (let j = i + 1; j <= reach; j++) {
      cheapest = Math.min(cheapest, dp[j]);
    }
    dp[i] = prices[i] + cheapest;
  }
  return dp[0];
}

