function minimumCoins(prices) {
  const n = prices.length;
  let best = Infinity;
  for (let mask = 0; mask < (1 << n); mask++) {
    let cost = 0;
    let ok = true;
    for (let j = 0; j < n && ok; j++) {
      if (mask & (1 << j)) { cost += prices[j]; continue; }
      let free = false;
      for (let k = 0; k < j; k++) if ((mask & (1 << k)) && j <= 2 * k + 1) free = true;
      if (!free) ok = false;
    }
    if (ok && cost < best) best = cost;
  }
  return best;
}

